@CanIgnoreReturnValue
protected final @Nullable T endOfData() {
  state = State.DONE;
  return null;
}

@Override
public final boolean hasNext() {
  checkState(state != State.FAILED);
  switch (state) {
    case DONE:
      return false;
    case READY:
      return true;
    default:
  }
  return tryToComputeNext();
}

@Override
@ParametricNullness
public final T next() {
  if (!hasNext()) {
    throw new NoSuchElementException();
  }
  state = State.NOT_READY;
  // Safe because hasNext() ensures that tryToComputeNext() has put a T into `next`.
  T result = uncheckedCastNullableTToT(next);
  next = null;
  return result;
}

@Override
public final void remove() {
  throw new UnsupportedOperationException();
}

private boolean tryToComputeNext() {
  state = State.FAILED; // temporary pessimism
  next = computeNext();
  if (state != State.DONE) {
    state = State.READY;
    return true;
  }
  return false;
}

Ascii.java::Ascii.equalsIgnoreCase.source:
public static boolean equalsIgnoreCase(CharSequence s1, CharSequence s2) {
  // Calling length() is the null pointer check (so do it before we can exit early).
  int length = s1.length();
  if (s1 == s2) {
    return true;
  }
  if (length != s2.length()) {
    return false;
  }
  for (int i = 0; i < length; i++) {
    char c1 = s1.charAt(i);
    char c2 = s2.charAt(i);
    if (c1 == c2) {
      continue;
    }
    int alphaIndex = getAlphaIndex(c1);
    // This was also benchmarked using '&' to avoid branching (but always evaluate the rhs),
    // however this showed no obvious improvement.
    if (alphaIndex < 26 && alphaIndex == getAlphaIndex(c2)) {
      continue;
    }
    return false;
  }
  return true;
}

Ascii.java::Ascii.getAlphaIndex.source:
private static int getAlphaIndex(char c) {
  // Fold upper-case ASCII to lower-case and make zero-indexed and unsigned (by casting to char).
  return (char) ((c | CASE_MASK) - 'a');
}

