CharMatcher.java::CharMatcher.precompute.source:
@GwtIncompatible // SmallCharMatcher
CharMatcher precomputedInternal() {
  BitSet table = new BitSet();
  setBits(table);
  int totalCharacters = table.cardinality();
  if (totalCharacters * 2 <= DISTINCT_CHARS) {
    return precomputedPositive(totalCharacters, table, toString());
  } else {
    // TODO(lowasser): is it worth it to worry about the last character of large matchers?
    table.flip(Character.MIN_VALUE, Character.MAX_VALUE + 1);
    int negatedCharacters = DISTINCT_CHARS - totalCharacters;
    String suffix = ".negate()";
    String description = toString();
    String negatedDescription =
        description.endsWith(suffix)
            ? description.substring(0, description.length() - suffix.length())
            : description + suffix;
    return new NegatedFastMatcher(
        precomputedPositive(negatedCharacters, table, negatedDescription)) {
      @Override
      public String toString() {
        return description;
      }
    };
  }
}

@GwtIncompatible // SmallCharMatcher
private static CharMatcher precomputedPositive(
    int totalCharacters, BitSet table, String description) {
  switch (totalCharacters) {
    case 0:
      return none();
    case 1:
      return is((char) table.nextSetBit(0));
    case 2:
      char c1 = (char) table.nextSetBit(0);
      char c2 = (char) table.nextSetBit(c1 + 1);
      return isEither(c1, c2);
    default:
      return isSmall(totalCharacters, table.length())
          ? SmallCharMatcher.from(table, description)
          : new BitSetMatcher(table, description);
  }
}

CharMatcher.java::CharMatcher.removeFrom.source:
public String removeFrom(CharSequence sequence) {
  String string = sequence.toString();
  int pos = indexIn(string);
  if (pos == -1) {
    return string;
  }

  char[] chars = string.toCharArray();
  int spread = 1;

  // This unusual loop comes from extensive benchmarking
  OUT:
  while (true) {
    pos++;
    while (true) {
      if (pos == chars.length) {
        break OUT;
      }
      if (matches(chars[pos])) {
        break;
      }
      chars[pos - spread] = chars[pos];
      pos++;
    }
    spread++;
  }
  return new String(chars, 0, pos - spread);
}

CharMatcher.java::CharMatcher.replaceFro.source:
public String replaceFrom(CharSequence sequence, char replacement) {
  String string = sequence.toString();
  int pos = indexIn(string);
  if (pos == -1) {
    return string;
  }
  char[] chars = string.toCharArray();
  chars[pos] = replacement;
  for (int i = pos + 1; i < chars.length; i++) {
    if (matches(chars[i])) {
      chars[i] = replacement;
    }
  }
  return new String(chars);
}

public String replaceFrom(CharSequence sequence, CharSequence replacement) {
  int replacementLen = replacement.length();
  if (replacementLen == 0) {
    return removeFrom(sequence);
  }
  if (replacementLen == 1) {
    return replaceFrom(sequence, replacement.charAt(0));
  }

  String string = sequence.toString();
  int pos = indexIn(string);
  if (pos == -1) {
    return string;
  }

  int len = string.length();
  StringBuilder buf = new StringBuilder((len * 3 / 2) + 16);

  int oldpos = 0;
  do {
    buf.append(string, oldpos, pos);
    buf.append(replacement);
    oldpos = pos + 1;
    pos = indexIn(string, oldpos);
  } while (pos != -1);

  buf.append(string, oldpos, len);
  return buf.toString();
}

